", posicao); printf("%s
", lista_complexidade_ordenacao(LISTA_ORDENACAO_INSERTION)); printf("%s
", lista_complexidade_busca(LISTA_BUSCA_BINARIA)); lista_remover_posicao(&lista, 2U, &removido); printf("Removido: %d
", removido); /* Removido: 20 */ lista_imprimir(&lista); /* [ 10, 15, 30 ] */ lista_destruir(&lista); return 0; }
